const FNV_PRIME = 0x100000001b3n;
const MASK_64 = 0xffffffffffffffffn;

/** 64-bit FNV-1a over the UTF-16 code units of a string, as 16 hex digits. */
function fnv1a64(text: string): string {
  let hash = FNV_OFFSET;
  for (let index = 0; index < text.length; index++) {
    const unit = text.charCodeAt(index);
    hash = ((hash ^ BigInt(unit & 0xff)) * FNV_PRIME) & MASK_64;
    hash = ((hash ^ BigInt(unit >>> 8)) * FNV_PRIME) & MASK_64;
  }
  return hash.toString(16).padStart(16, "0");
}

/** Move data is immutable, so each moveset object is hashed once. */
const versions = new WeakMap<DuelMoveset, string>();

/**
 * Identifies a moveset by its data: the 64-bit hash of all of it. A duel state records it, and restoring, replaying
 * or stepping a duel against other data is refused, so changed data can never keep an old version.
 */
export function movesetVersion(moveset: DuelMoveset): string {
  let version = versions.get(moveset);
  if (version === undefined) {
    version = fnv1a64(canonical(moveset));
    versions.set(moveset, version);
  }
  return version;
}
import { duelistMoveset, movesetVersion, type DuelButton, type DuelMove, type DuelMoveset } from "@pirate-sea-race/content/moves";
import type { Facing } from "./boxes.js";

/** Static duel data the step reads; it never changes during a duel. */
export interface DuelConfig {
  readonly moveset: DuelMoveset;
}

export const defaultDuelConfig: DuelConfig = { moveset: duelistMoveset };

/**
 * What a fighter is doing. `idle`, `walk` and `crouch` are free: the fighter can start anything on the next frame.
 * `jump` lasts until landing. The others are timed by `timer`.
 */
export type FighterAction =
  | "idle"
  | "walk"
  | "crouch"
  | "jump"
  | "dash"
  | "backdash"
  | "attack"
  | "hitstun"
  | "blockstun"
  | "stagger"
  | "thrown"
  | "throw-break"
  | "knockdown";

export type Stance = "standing" | "crouching" | "airborne";

/** Frames each button press stays usable (0 = no press waiting). */
export type InputBuffer = Readonly<Record<DuelButton, number>>;

/**
 * One fighter. Every number is an integer: positions in sub-pixels (x from the left wall, y up from the floor, the
 * origin in the middle of the feet), velocities in sub-pixels per frame, durations in frames.
