import { rulesPresets } from "@pirate-sea-race/content";
import { presetRubbings, presetRubbingTypes } from "@pirate-sea-race/content/objectives";
import { canonicalize } from "../hash.js";
import { activeDuelOf, cacheRubbings, findCache, findDuel, findPlayer, findSource, type LedgerState } from "./state.js";

/**
 * Every rule the ledger must keep between operations (§4, §12, §19 "Inventory correctness"), as a list of
 * violations; empty when the state is sound:
 *
 * - every rubbing id of the preset is present exactly once, with its type, and no other rubbing exists;
 * - each rubbing has one valid location: its own source, a player still in the match, an existing cache, or a
 *   reservation for one of the two players of an unresolved duel;
 * - no player holds (owns or has reserved) two rubbings of one type;
 * - no cache is empty; a player in an unresolved duel owns nothing outside it, is in only one, and has no channel;
 * - gold balances are non-negative integers that sum to the gold players brought in.
 */
export function checkLedger(state: LedgerState): string[] {
  const problems: string[] = [];
  try {
    canonicalize(state);
  } catch (error) {
    problems.push(`state is not plain integer data: ${(error as Error).message}`);
  }
  const preset = rulesPresets[state.preset];
  const expected = presetRubbings(preset);
  const types = presetRubbingTypes(preset);
  if (state.types.join(",") !== types.join(",")) problems.push(`types ${state.types.join(",")} are not the preset's ${types.join(",")}`);

  const seen = new Map<string, number>();
  for (const rubbing of state.rubbings) seen.set(rubbing.id, (seen.get(rubbing.id) ?? 0) + 1);
  for (const { id, type } of expected) {
    const count = seen.get(id) ?? 0;
    if (count !== 1) problems.push(`rubbing ${id} is present ${count} times`);
    const rubbing = state.rubbings.find((candidate) => candidate.id === id);
    if (rubbing && rubbing.type !== type) problems.push(`rubbing ${id} has type ${rubbing.type}, not ${type}`);
    seen.delete(id);
  }
  for (const id of seen.keys()) problems.push(`rubbing ${id} is not one of the preset's`);
  if (state.rubbings.length !== expected.length) problems.push(`${state.rubbings.length} rubbings instead of ${expected.length}`);

  if (state.sources.length !== expected.length) problems.push(`${state.sources.length} sources instead of ${expected.length}`);
  const sealed = new Set(state.sources.map((source) => source.rubbingId));
  if (sealed.size !== expected.length) problems.push("two sources seal the same rubbing");

  for (const rubbing of state.rubbings) {
    const location = rubbing.location;
    const where = `rubbing ${rubbing.id}`;
    if (!Number.isSafeInteger(rubbing.revision) || rubbing.revision < 0) problems.push(`${where} has revision ${rubbing.revision}`);
    switch (location.kind) {
      case "source": {
        const source = findSource(state, location.sourceId);
        if (!source) problems.push(`${where} is at unknown source ${location.sourceId}`);
        else if (source.rubbingId !== rubbing.id) problems.push(`${where} is at ${source.id}, which seals ${source.rubbingId}`);
        break;
      }
      case "player": {
        const player = findPlayer(state, location.playerId);
        if (!player) problems.push(`${where} belongs to unknown player ${location.playerId}`);
        else if (player.status === "left") problems.push(`${where} belongs to ${player.id}, who left`);
        else if (activeDuelOf(state, player.id)) problems.push(`${where} is owned by ${player.id} outside their duel`);
        break;
      }
      case "cache":
        if (!findCache(state, location.cacheId)) problems.push(`${where} is in unknown cache ${location.cacheId}`);
        break;
      case "duel": {
        const duel = findDuel(state, location.duelId);
        if (!duel) problems.push(`${where} is reserved in unknown duel ${location.duelId}`);
        else if (duel.phase === "settled") problems.push(`${where} is reserved in settled duel ${duel.id}`);
        else if (!duel.players.includes(location.playerId)) problems.push(`${where} is reserved for ${location.playerId}, not in ${duel.id}`);
        break;
      }
      default:
        problems.push(`${where} has no valid location`);
    }
  }

  let gold = 0;
  for (const player of state.players) {
    const held = state.rubbings.filter(
      (rubbing) =>
        (rubbing.location.kind === "player" || rubbing.location.kind === "duel") && rubbing.location.playerId === player.id,
    );
    for (const type of types) {
      const count = held.filter((rubbing) => rubbing.type === type).length;
      if (count > 1) problems.push(`player ${player.id} holds ${count} ${type} rubbings`);
    }
    if (!Number.isSafeInteger(player.gold) || player.gold < 0) problems.push(`player ${player.id} has ${player.gold} gold`);
    gold += player.gold;
    const duels = state.duels.filter((duel) => duel.phase !== "settled" && duel.players.includes(player.id));
    if (duels.length > 1) problems.push(`player ${player.id} is in ${duels.length} unresolved duels`);
    if (player.channel !== null && (player.status !== "connected" || duels.length > 0)) {
      problems.push(`player ${player.id} channels while ${duels.length > 0 ? "in a duel" : player.status}`);
    }
    if ((player.status === "disconnected") !== (player.reservationDeadline !== null)) {
      problems.push(`player ${player.id} is ${player.status} with reservation deadline ${player.reservationDeadline}`);
    }
    if ((player.status === "left") !== (player.exit !== null)) problems.push(`player ${player.id} is ${player.status} with exit ${JSON.stringify(player.exit)}`);
    if (player.freshRumors.some((type, index) => !types.includes(type) || player.freshRumors.indexOf(type) !== index)) {
      problems.push(`player ${player.id} has fresh rumors ${player.freshRumors.join(",")}`);
    }
  }
  if (gold !== state.goldIssued) problems.push(`balances sum to ${gold} gold, but ${state.goldIssued} was issued`);
  if (new Set(state.players.map((player) => player.id)).size !== state.players.length) problems.push("duplicate player ids");

  for (const cache of state.caches) {
    if (cacheRubbings(state, cache.id).length === 0) problems.push(`cache ${cache.id} is empty`);
  }
  if (new Set(state.caches.map((cache) => cache.id)).size !== state.caches.length) problems.push("duplicate cache ids");

  for (const duel of state.duels) {
    if (duel.phase === "fighting" && (duel.result !== null || duel.settlement !== null)) problems.push(`duel ${duel.id} fights with a result`);
    if (duel.phase === "choosing") {
      if (duel.result?.outcome !== "win" || duel.choiceDeadline === null) problems.push(`duel ${duel.id} chooses without a win`);
      else if (findPlayer(state, duel.result.winner ?? "")?.status === "left") problems.push(`duel ${duel.id} waits for a winner who left`);
    }
    if (duel.phase === "settled" && (duel.result === null || duel.settlement === null)) problems.push(`duel ${duel.id} settled without a result`);
    if (duel.phase === "fighting") {
      for (const playerId of duel.players) {
        if (findPlayer(state, playerId)?.status === "left") problems.push(`duel ${duel.id} fights on without ${playerId}, who left`);
      }
    }
  }
  if (new Set(state.duels.map((duel) => duel.id)).size !== state.duels.length) problems.push("duplicate duel ids");
  return problems;
}

/** Throws with every violation when the ledger breaks its invariant. */
export function assertLedger(state: LedgerState): void {
  const problems = checkLedger(state);
  if (problems.length > 0) throw new Error(`ledger invariant broken:\n${problems.join("\n")}`);
}

