        "start-claim:type-held",
        "chosen-theft:type",
        "default-theft:type",
        "settled-without-choice",
        "choose:ineligible-type",
        "choose:not-winner",
        "result:ok",
        "result:already-resolved",
        "repeat:already-resolved",
        "repeat:duplicate",
        "reserve:player-in-duel",
        "theft",
        "win-without-theft",
        "gold-suppressed",
        "forfeit",
        "disconnect:ok",
        "reconnect:ok",
        "reconnect:reservation-expired",
        "expire:ok",
        "expire:reservation-active",
        "quit:ok",
        "quit-in-duel:choosing",
        "caches",
        "rumors",
        "stale:stale-tick",
