const SEEDS = [1, 2, 3, 4];
const STEPS = 1500;

describe("ledger property: no rubbing is ever lost or duplicated (§19)", () => {
  for (const preset of ["slice", "alpha"] as const) {
    it(`keeps the invariant through ${SEEDS.length} × ${STEPS} random ${preset} operations and replays identically`, () => {
      const totals: Stats = {};
      for (const seed of SEEDS) {
        const first = simulate(preset, seed, STEPS);
        // The replay skips the per-step checks, which draw nothing from the dice, so it is the same sequence.
        const again = simulate(preset, seed, STEPS, false);
        expect(hashState(again.state)).toBe(hashState(first.state));
        expect(again.stats).toEqual(first.stats);
        for (const [key, value] of Object.entries(first.stats)) totals[key] = (totals[key] ?? 0) + value;
      }
      // Each rule the sequences are meant to exercise actually happened, so the invariant was not checked vacuously.
      for (const key of [
        "status:collected",
        "status:claimed",
        "status:failed",
        "status:reset",
        "status:cancelled",
        "start-collect:type-held",
        "start-claim:type-held",
        "chosen-theft:type",
        "default-theft:type",
        "settled-without-choice",
        "choose:ineligible-type",
        "choose:not-winner",
        "result:ok",
        "result:already-resolved",
        "repeat:already-resolved",
        "repeat:duplicate",
        "reserve:player-in-duel",
        "theft",
        "win-without-theft",
        "gold-suppressed",
        "forfeit",
        "disconnect:ok",
        "reconnect:ok",
        "reconnect:reservation-expired",
        "expire:ok",
        "expire:reservation-active",
        "quit:ok",
        "quit-in-duel:choosing",
        "caches",
        "rumors",
        "stale:stale-tick",
      ]) {
        expect({ key, count: totals[key] ?? 0 }).toMatchObject({ key, count: expect.any(Number) });
        expect(totals[key] ?? 0, key).toBeGreaterThan(0);
      }
    });
  }

  it("replays to a different state from a different seed", () => {
    expect(hashState(simulate("alpha", 7, 1500).state)).not.toBe(hashState(simulate("alpha", 8, 1500).state));
  });
});

